import{_ as r,o as l,c as t,a3 as o}from"./chunks/framework.DBpCFmh2.js";const h=JSON.parse('{"title":"ReAct 推理循环","description":"本文件聚焦于 ReAct 推理循环的实现，围绕“思考-行动-观察”主循环、工具调用协调、循环检测、子任务管理、反思机制以及错误恢复展开。","frontmatter":{"title":"ReAct 推理循环","description":"本文件聚焦于 ReAct 推理循环的实现，围绕“思考-行动-观察”主循环、工具调用协调、循环检测、子任务管理、反思机制以及错误恢复展开。"},"headers":[],"relativePath":"智能对话系统/ReAct-推理循环/index.md","filePath":"智能对话系统/ReAct-推理循环/index.md","lastUpdated":null}'),a={name:"智能对话系统/ReAct-推理循环/index.md"};function i(c,e,n,u,s,b){return l(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="react-推理循环" tabindex="-1">ReAct 推理循环 <a class="header-anchor" href="#react-推理循环" aria-label="Permalink to &quot;ReAct 推理循环&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js" target="_blank" rel="noreferrer">src/background/react-loop.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js" target="_blank" rel="noreferrer">src/background/react-reflection.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/loop-detector.js" target="_blank" rel="noreferrer">src/background/loop-detector.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js" target="_blank" rel="noreferrer">src/background/tool-executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/subagent-depth.js" target="_blank" rel="noreferrer">src/background/subagent-depth.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/completion-verifier.js" target="_blank" rel="noreferrer">src/background/completion-verifier.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与预算控制">性能与预算控制</a></li><li><a href="#调试与故障排查">调试与故障排查</a></li><li><a href="#结论">结论</a></li><li><a href="#附录扩展指南">附录：扩展指南</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件聚焦于 ReAct 推理循环的实现，围绕“思考-行动-观察”主循环、工具调用协调、循环检测、子任务管理、反思机制以及错误恢复展开。重点解析 reactLoopImpl 的核心流程，包括消息处理、工具执行调度、结果缓存、上下文压缩、检查点持久化与恢复；并说明 shouldReflect、buildReflectionPrompt、reflectOnResult 的反思策略；同时梳理 loop-detector 的多模式检测（重复操作、元素枚举、振荡、失败作用域、无进展滚动、预算控制）。文档还提供扩展新工具类型、自定义 ReAct 行为与优化推理性能的实践建议，以及常见问题的定位方法。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>ReAct 推理循环位于扩展端 background 脚本中，由多个模块协作完成：</p><ul><li>react-loop.js：ReAct 主循环、工具执行编排、子任务派发、上下文压缩、检查点、反思入口。</li><li>react-reflection.js：后置反思与子任务反思的 Prompt 构建、API 调用与结果解析。</li><li>loop-detector.js：多模式循环检测器（纯逻辑，browser-free）。</li><li>tool-executor.js：工具定义、动态注册（MCP/RAG）、执行分发与超时。</li><li>subagent-depth.js：统一的子代理/子任务嵌套深度计数器。</li><li>completion-verifier.js：完成度校验编排层（取证、评审、重跑指令构造）。</li></ul><pre class="mermaid">graph TB
RL[&quot;react-loop.js&lt;br/&gt;ReAct 主循环&quot;] --&gt; TE[&quot;tool-executor.js&lt;br/&gt;工具定义与执行&quot;]
RL --&gt; RD[&quot;loop-detector.js&lt;br/&gt;循环检测器&quot;]
RL --&gt; RR[&quot;react-reflection.js&lt;br/&gt;反思机制&quot;]
RL --&gt; CV[&quot;completion-verifier.js&lt;br/&gt;完成度校验编排&quot;]
RL --&gt; SD[&quot;subagent-depth.js&lt;br/&gt;嵌套深度计数&quot;]
TE --&gt; |调用 Agent/MCP/浏览器能力| Ext[&quot;扩展端能力&quot;]
</pre><p>图表来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L752-L1202" target="_blank" rel="noreferrer">src/background/react-loop.js#L752-L1202</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L551-L644" target="_blank" rel="noreferrer">src/background/tool-executor.js#L551-L644</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/loop-detector.js#L266-L439" target="_blank" rel="noreferrer">src/background/loop-detector.js#L266-L439</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L259-L487" target="_blank" rel="noreferrer">src/background/react-reflection.js#L259-L487</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/completion-verifier.js#L84-L147" target="_blank" rel="noreferrer">src/background/completion-verifier.js#L84-L147</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/subagent-depth.js#L15-L52" target="_blank" rel="noreferrer">src/background/subagent-depth.js#L15-L52</a></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1-L109" target="_blank" rel="noreferrer">src/background/react-loop.js#L1-L109</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1-L23" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1-L23</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li>ReAct 主循环（reactLoopImpl） <ul><li>负责消息预处理、API 调用、工具执行、结果缓存、上下文压缩、检查点保存与恢复、反思触发。</li></ul></li><li>工具执行器（tool-executor） <ul><li>提供工具定义、动态注册（MCP/RAG）、参数解析、执行分发、超时与确认门控。</li></ul></li><li>循环检测器（loop-detector） <ul><li>六模式检测：重复、ref 枚举、ABAB 振荡、失败作用域、导航重置、无进展滚动，并提供软提醒与硬停。</li></ul></li><li>反思机制（react-reflection） <ul><li>后置反思 with 评估/修订解耦，子任务反思独立评分与可选修订。</li></ul></li><li>完成度校验（completion-verifier） <ul><li>客观断言取证、命令/文件类判据、DOM 类判据、重跑指令生成。</li></ul></li><li>嵌套深度（subagent-depth） <ul><li>plan_task 与 dispatch_task 共享深度计数，防止递归爆炸。</li></ul></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L752-L1202" target="_blank" rel="noreferrer">src/background/react-loop.js#L752-L1202</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L551-L644" target="_blank" rel="noreferrer">src/background/tool-executor.js#L551-L644</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/loop-detector.js#L11-L21" target="_blank" rel="noreferrer">src/background/loop-detector.js#L11-L21</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L57-L79" target="_blank" rel="noreferrer">src/background/react-reflection.js#L57-L79</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/completion-verifier.js#L84-L147" target="_blank" rel="noreferrer">src/background/completion-verifier.js#L84-L147</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/subagent-depth.js#L15-L52" target="_blank" rel="noreferrer">src/background/subagent-depth.js#L15-L52</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>下图展示 ReAct 主循环在一次迭代中的关键路径：模型响应后进入工具执行分支，并行或顺序执行工具，记录执行日志，轮末喂入循环检测器，必要时注入系统提醒；若无工具调用则进入最终答案分支，触发后置反思并返回结果。</p><pre class="mermaid">sequenceDiagram
participant Model as &quot;语言模型&quot;
participant Loop as &quot;reactLoopImpl&quot;
participant Tools as &quot;工具执行器&quot;
participant Detector as &quot;循环检测器&quot;
participant Reflection as &quot;反思机制&quot;
Loop-&gt;&gt;Model : 发送消息+工具定义
Model--&gt;&gt;Loop : assistant(tool_calls)/content
alt 有工具调用
Loop-&gt;&gt;Tools : 执行工具并行/顺序
Tools--&gt;&gt;Loop : 工具结果
Loop-&gt;&gt;Detector : 轮末记录(toolName,args,result)
Detector--&gt;&gt;Loop : nudge/stop
opt 软提醒
Loop-&gt;&gt;Loop : 注入系统提醒到消息历史
end
else 无工具调用
Loop-&gt;&gt;Reflection : shouldReflect? buildReflectionPrompt? reflectOnResult?
Reflection--&gt;&gt;Loop : 质量评估/修订结果
end
Loop--&gt;&gt;Loop : 保存检查点/清理
</pre><p>图表来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1256-L1644" target="_blank" rel="noreferrer">src/background/react-loop.js#L1256-L1644</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1676-L2319" target="_blank" rel="noreferrer">src/background/react-loop.js#L1676-L2319</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/loop-detector.js#L304-L439" target="_blank" rel="noreferrer">src/background/loop-detector.js#L304-L439</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L259-L487" target="_blank" rel="noreferrer">src/background/react-reflection.js#L259-L487</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="reactloopimpl-思考-行动-观察主循环" tabindex="-1">reactLoopImpl：思考-行动-观察主循环 <a class="header-anchor" href="#reactloopimpl-思考-行动-观察主循环" aria-label="Permalink to &quot;reactLoopImpl：思考-行动-观察主循环&quot;">​</a></h3><ul><li>消息处理 <ul><li>应用不可信内容安全合约、过滤内部字段、剥离历史图片、上下文压力评估与主动裁剪、任务锚点与便签瞬态回注。</li></ul></li><li>API 调用 <ul><li>流式与非流式统一封装，带外层超时 watchdog、重试回调、usage 统计与 token 校准。</li></ul></li><li>工具执行调度 <ul><li>按 tool_calls 声明顺序分组并行（PARALLELIZABLE_TOOLS），plan_task 独占语义，clarify_question 暂停整体计时。</li></ul></li><li>结果缓存 <ul><li>单次循环内 Map 缓存，TTL=60s，并行工具命中仍喂入检测器避免重复检测失效。</li></ul></li><li>执行日志与快照 <ul><li>增量发送 EXECUTION_STATUS_UPDATE，内存窗口裁剪，checkpoint 节流保存。</li></ul></li><li>子任务管理 <ul><li>plan_task 拆解后 executeSubtasks，支持 sequential/parallel/dependency 策略，失败策略 stop/continue/skip，回滚已完成子任务。</li></ul></li><li>反思入口 <ul><li>最终答案完成后根据 shouldReflect 决定是否进行后置反思。</li></ul></li></ul><pre class="mermaid">flowchart TD
Start([&quot;进入 reactLoopImpl&quot;]) --&gt; Prep[&quot;消息预处理/上下文压力评估&quot;]
Prep --&gt; CallAPI[&quot;调用模型 API流式/非流式&quot;]
CallAPI --&gt; HasTools{&quot;是否包含 tool_calls?&quot;}
HasTools --&gt; |是| Group[&quot;分组并行/顺序执行工具&quot;]
Group --&gt; ExecTool[&quot;executeSingleToolCall&quot;]
ExecTool --&gt; CacheCheck{&quot;缓存命中?&quot;}
CacheCheck --&gt; |是| FeedDetector[&quot;喂入循环检测器&quot;]
CacheCheck --&gt; |否| RunTool[&quot;执行工具/超时/澄清暂停&quot;]
RunTool --&gt; FormatRes[&quot;格式化结果/截断/卸载&quot;]
FormatRes --&gt; FeedDetector
FeedDetector --&gt; Flush[&quot;轮末 flushLoopRecords&quot;]
Flush --&gt; SaveCP[&quot;保存检查点&quot;]
SaveCP --&gt; NextIter[&quot;下一轮&quot;]
HasTools --&gt; |否| Finalize[&quot;最终答案分支&quot;]
Finalize --&gt; Reflect{&quot;shouldReflect?&quot;}
Reflect --&gt; |是| PostReflect[&quot;reflectOnResult(评估/修订)&quot;]
Reflect --&gt; |否| Return[&quot;返回结果&quot;]
PostReflect --&gt; Return
</pre><p>图表来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L752-L1202" target="_blank" rel="noreferrer">src/background/react-loop.js#L752-L1202</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1256-L1644" target="_blank" rel="noreferrer">src/background/react-loop.js#L1256-L1644</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1676-L2319" target="_blank" rel="noreferrer">src/background/react-loop.js#L1676-L2319</a></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L752-L1202" target="_blank" rel="noreferrer">src/background/react-loop.js#L752-L1202</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1256-L1644" target="_blank" rel="noreferrer">src/background/react-loop.js#L1256-L1644</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1676-L2319" target="_blank" rel="noreferrer">src/background/react-loop.js#L1676-L2319</a></li></ul><h3 id="工具调用协调机制" tabindex="-1">工具调用协调机制 <a class="header-anchor" href="#工具调用协调机制" aria-label="Permalink to &quot;工具调用协调机制&quot;">​</a></h3><ul><li>用户确认门控 <ul><li>敏感工具/action 级确认，支持“当前任务放行”，会话级关联键防串扰，面板呈现回执后才开始倒计时。</li></ul></li><li>并行执行 <ul><li>连续可并行工具合并为一组 Promise.all，非并行工具单独执行；plan_task 会中断同轮后续工具。</li></ul></li><li>结果缓存 <ul><li>仅并行工具缓存，TTL=60s，命中时仍记录 loopRecords 以维持重复检测能力。</li></ul></li><li>工具观察提示 <ul><li>失败/空结果/超大结果时追加规则提示，引导模型自我调整，零额外 LLM 调用。</li></ul></li></ul><pre class="mermaid">classDiagram
class ReactLoop {
+executeSingleToolCall()
+dispatchSubtasksParallel()
+flushLoopRecords()
}
class ToolExecutor {
+executeTool()
+loadMcpTools()
+unloadMcpTools()
}
class LoopDetector {
+record(tabId, name, args, result)
}
ReactLoop --&gt; ToolExecutor : &quot;调用工具&quot;
ReactLoop --&gt; LoopDetector : &quot;轮末喂入记录&quot;
</pre><p>图表来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1676-L2319" target="_blank" rel="noreferrer">src/background/react-loop.js#L1676-L2319</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L551-L644" target="_blank" rel="noreferrer">src/background/tool-executor.js#L551-L644</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/loop-detector.js#L304-L439" target="_blank" rel="noreferrer">src/background/loop-detector.js#L304-L439</a></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1676-L2319" target="_blank" rel="noreferrer">src/background/react-loop.js#L1676-L2319</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L551-L644" target="_blank" rel="noreferrer">src/background/tool-executor.js#L551-L644</a></li></ul><h3 id="循环检测算法-多模式" tabindex="-1">循环检测算法（多模式） <a class="header-anchor" href="#循环检测算法-多模式" aria-label="Permalink to &quot;循环检测算法（多模式）&quot;">​</a></h3><ul><li>重复检测（窗口制） <ul><li>相同 toolName+args+result 在窗口内重复达到阈值即软提醒，超过停止阈值硬停。</li></ul></li><li>ref 枚举循环 <ul><li>query_elements 专用：非法页、重读且结果不变、乱序跳页累计可疑计数，超阈硬停。</li></ul></li><li>ABAB 振荡 <ul><li>最近尾迹 A,B,A,B 交替判定，全交替硬停，部分交替软提醒。</li></ul></li><li>失败作用域 <ul><li>白名单工具（interact_element/fill_form/select_dropdown/keyboard_input/file_upload）对同一目标连续失败达阈值硬停。</li></ul></li><li>无进展滚动 <ul><li>scroll_to(target=top/bottom/coordinates) 报告未移动多次硬停。</li></ul></li><li>预算控制 <ul><li>全局提醒预算达到阈值硬停，避免多模式软提醒累积导致长时无进展。</li></ul></li></ul><pre class="mermaid">flowchart TD
Rec[&quot;record(tabId,name,args,result)&quot;] --&gt; Nav{&quot;是否导航重置信号?&quot;}
Nav --&gt; |是| Reset[&quot;重置页面状态&quot;]
Nav --&gt; |否| Window[&quot;入窗/入尾迹&quot;]
Window --&gt; Repeat[&quot;重复检测&quot;]
Window --&gt; RefEnum[&quot;ref 枚举更新&quot;]
Window --&gt; FailScope[&quot;失败作用域&quot;]
Window --&gt; Scroll[&quot;无进展滚动&quot;]
Repeat --&gt; CheckStop{&quot;达到停止阈值?&quot;}
RefEnum --&gt; CheckStop
FailScope --&gt; CheckStop
Scroll --&gt; CheckStop
CheckStop --&gt; |是| Stop[&quot;返回 stop(reason,params)&quot;]
CheckStop --&gt; |否| Nudge[&quot;收集软提醒&quot;]
Nudge --&gt; Budget[&quot;预算计数&quot;]
Budget --&gt; |超阈| Stop
Budget --&gt; |未超| None[&quot;返回 none&quot;]
</pre><p>图表来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/loop-detector.js#L304-L439" target="_blank" rel="noreferrer">src/background/loop-detector.js#L304-L439</a></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/loop-detector.js#L11-L21" target="_blank" rel="noreferrer">src/background/loop-detector.js#L11-L21</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/loop-detector.js#L304-L439" target="_blank" rel="noreferrer">src/background/loop-detector.js#L304-L439</a></li></ul><h3 id="子任务管理与执行" tabindex="-1">子任务管理与执行 <a class="header-anchor" href="#子任务管理与执行" aria-label="Permalink to &quot;子任务管理与执行&quot;">​</a></h3><ul><li>策略 <ul><li>sequential/parallel/dependency（拓扑排序），失败策略 stop/continue/skip，最大并发默认 3。</li></ul></li><li>防重放 <ul><li>成功子任务即时记入进度 Map，恢复后跳过重放，写操作二次执行风险规避。</li></ul></li><li>回滚 <ul><li>stop 策略下逆序回滚已完成子任务，记录 rolledback/rollback_failed 日志。</li></ul></li><li>超时与预算 <ul><li>子任务整体超时上限 15 分钟，受父任务剩余时间约束；computeSubtaskLoopTimeoutMs 保证最小 60s。</li></ul></li><li>完成度校验 <ul><li>Phase B：子任务成功当场取证（DOM/命令/文件），可配置 rerunEnabled 驱动重跑回路，严格真子集判定防振荡。</li></ul></li></ul><pre class="mermaid">flowchart TD
Plan[&quot;plan_task 结果&quot;] --&gt; Strategy{&quot;strategy&quot;}
Strategy --&gt; Seq[&quot;sequential/dependency&quot;]
Strategy --&gt; Par[&quot;parallel&quot;]
Seq --&gt; ExecSeq[&quot;顺序执行 executeSingleSubtask&quot;]
Par --&gt; ExecPar[&quot;dispatchSubtasksParallel 并发受限池&quot;]
ExecSeq --&gt; Done[&quot;onDone 进度回写/Checkpoint&quot;]
ExecPar --&gt; Done
Done --&gt; Verify[&quot;完成度校验 annotateOneSubtaskCompletion&quot;]
Verify --&gt; Rerun{&quot;rerunEnabled?&quot;}
Rerun --&gt; |是| Directive[&quot;缺项指令追加 user 消息&quot;]
Directive --&gt; ReRun[&quot;reactLoop 再跑一轮&quot;]
Rerun --&gt; |否| Result[&quot;返回子任务结果&quot;]
</pre><p>图表来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L2503-L3119" target="_blank" rel="noreferrer">src/background/react-loop.js#L2503-L3119</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/completion-verifier.js#L454-L518" target="_blank" rel="noreferrer">src/background/completion-verifier.js#L454-L518</a></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L2503-L3119" target="_blank" rel="noreferrer">src/background/react-loop.js#L2503-L3119</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/completion-verifier.js#L454-L518" target="_blank" rel="noreferrer">src/background/completion-verifier.js#L454-L518</a></li></ul><h3 id="反思机制-shouldreflect-buildreflectionprompt-reflectonresult" tabindex="-1">反思机制：shouldReflect / buildReflectionPrompt / reflectOnResult <a class="header-anchor" href="#反思机制-shouldreflect-buildreflectionprompt-reflectonresult" aria-label="Permalink to &quot;反思机制：shouldReflect / buildReflectionPrompt / reflectOnResult&quot;">​</a></h3><ul><li>shouldReflect <ul><li>子任务内部不触发；存在 plan_task、工具失败、或工具调用次数≥2 时触发。</li></ul></li><li>buildReflectionPrompt <ul><li>提取用户问题、工具执行详情、计划信息，输出结构化 JSON 评分维度。</li></ul></li><li>reflectOnResult <ul><li>评估/修订解耦：先轻量评估，低于质量阈值才发起修订调用；支持多轮，记录 reflectionLog，最终决策 passed/revised/needs_improvement。</li></ul></li></ul><pre class="mermaid">flowchart TD
Start([&quot;后置反思入口&quot;]) --&gt; Should{&quot;shouldReflect(executionLog, taskContext)?&quot;}
Should --&gt; |否| Skip[&quot;跳过反思&quot;]
Should --&gt; |是| Build[&quot;buildReflectionPrompt(messages, answer, executionLog)&quot;]
Build --&gt; CallEval[&quot;callApi(prompt, maxTokens)&quot;]
CallEval --&gt; Parse[&quot;parseReflectionResult(rawContent)&quot;]
Parse --&gt; Decision{&quot;overallScore &gt;= qualityThreshold?&quot;}
Decision --&gt; |是| Pass[&quot;passed&quot;]
Decision --&gt; |否| Revise[&quot;buildRevisionPrompt + callApi(revise)&quot;]
Revise --&gt; ParseRev[&quot;parseRevisionAnswer(refinedAnswer)&quot;]
ParseRev --&gt; Apply{&quot;refinedAnswer 可用?&quot;}
Apply --&gt; |是| Revised[&quot;revised (wasRevised=true)&quot;]
Apply --&gt; |否| Needs[&quot;needs_improvement&quot;]
Pass --&gt; End([&quot;返回 content/reflectionLog/status&quot;])
Revised --&gt; End
Needs --&gt; End
</pre><p>图表来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L57-L79" target="_blank" rel="noreferrer">src/background/react-reflection.js#L57-L79</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L87-L153" target="_blank" rel="noreferrer">src/background/react-reflection.js#L87-L153</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L259-L487" target="_blank" rel="noreferrer">src/background/react-reflection.js#L259-L487</a></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L57-L79" target="_blank" rel="noreferrer">src/background/react-reflection.js#L57-L79</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L87-L153" target="_blank" rel="noreferrer">src/background/react-reflection.js#L87-L153</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L259-L487" target="_blank" rel="noreferrer">src/background/react-reflection.js#L259-L487</a></li></ul><h3 id="错误恢复与检查点" tabindex="-1">错误恢复与检查点 <a class="header-anchor" href="#错误恢复与检查点" aria-label="Permalink to &quot;错误恢复与检查点&quot;">​</a></h3><ul><li>检查点保存 <ul><li>初始、plan_task 完成、tools_completed、final_answer、error/user_cancelled 等时机保存；节流 1500ms，子任务不保存。</li></ul></li><li>恢复流程 <ul><li>resumeReactLoopFromCheckpoint 读取 IndexedDB，清理不完整消息配对，注入恢复提示，重新调用 reactLoop，携带 checkpoint 状态（taskState/subtaskPlan/subtaskProgress/notesState）。</li></ul></li><li>异常处理 <ul><li>AbortError 传播取消语义；StreamIdleTimeout 本地化提示；HTTP 400 上下文超限自愈（最多 3 次，逐档更激进裁剪）。</li></ul></li></ul><pre class="mermaid">flowchart TD
CPSave[&quot;saveCheckpointNow(reason, force)&quot;] --&gt; Persist[&quot;IndexedDB 写入 + 读回验证&quot;]
CPRead[&quot;getReactCheckpoint(sessionId)&quot;] --&gt; Clean[&quot;cleanupIncompleteMessagePairs&quot;]
Clean --&gt; Inject[&quot;注入恢复提示/用户指导&quot;]
Inject --&gt; ReRun[&quot;reactLoop(..., resumeState)&quot;]
ReRun --&gt; Clear[&quot;clearCheckpoint(sessionId)&quot;]
</pre><p>图表来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L547-L583" target="_blank" rel="noreferrer">src/background/react-loop.js#L547-L583</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L645-L726" target="_blank" rel="noreferrer">src/background/react-loop.js#L645-L726</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1044-L1092" target="_blank" rel="noreferrer">src/background/react-loop.js#L1044-L1092</a></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L547-L583" target="_blank" rel="noreferrer">src/background/react-loop.js#L547-L583</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L645-L726" target="_blank" rel="noreferrer">src/background/react-loop.js#L645-L726</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1044-L1092" target="_blank" rel="noreferrer">src/background/react-loop.js#L1044-L1092</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li>react-loop.js 依赖 <ul><li>tool-executor.js：工具定义、执行、MCP/RAG 动态注册。</li><li>loop-detector.js：多模式循环检测。</li><li>react-reflection.js：后置反思与子任务反思。</li><li>completion-verifier.js：完成度校验编排。</li><li>subagent-depth.js：嵌套深度计数。</li><li>state/config/stream-controller/token-counter 等基础设施。</li></ul></li></ul><pre class="mermaid">graph LR
RL[&quot;react-loop.js&quot;] --&gt; TE[&quot;tool-executor.js&quot;]
RL --&gt; LD[&quot;loop-detector.js&quot;]
RL --&gt; RR[&quot;react-reflection.js&quot;]
RL --&gt; CV[&quot;completion-verifier.js&quot;]
RL --&gt; SD[&quot;subagent-depth.js&quot;]
</pre><p>图表来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1-L21" target="_blank" rel="noreferrer">src/background/react-loop.js#L1-L21</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1-L23" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/loop-detector.js#L1-L9" target="_blank" rel="noreferrer">src/background/loop-detector.js#L1-L9</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L1-L7" target="_blank" rel="noreferrer">src/background/react-reflection.js#L1-L7</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/completion-verifier.js#L1-L19" target="_blank" rel="noreferrer">src/background/completion-verifier.js#L1-L19</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/subagent-depth.js#L1-L14" target="_blank" rel="noreferrer">src/background/subagent-depth.js#L1-L14</a></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1-L21" target="_blank" rel="noreferrer">src/background/react-loop.js#L1-L21</a></li></ul><h2 id="性能与预算控制" tabindex="-1">性能与预算控制 <a class="header-anchor" href="#性能与预算控制" aria-label="Permalink to &quot;性能与预算控制&quot;">​</a></h2><ul><li>Token 预算与上下文压缩 <ul><li>动态计算 reactTokenBudget（上下文窗口 - 实际 system prompt - 工具定义 - 输出预留 - 安全余量），阈值 80% 触发批量压缩，保留最近 2 轮原文，其余轮次一次 LLM 调用结构化摘要；仍超标则权重裁剪（反思 &gt; 工具结果 &gt; 普通消息）。</li></ul></li><li>工具结果截断与卸载 <ul><li>MAX_TOOL_RESULT_TOKENS=6000，优先卸载到 Agent workspace（保留完整可回读），失败则智能截断。</li></ul></li><li>流式空闲超时 <ul><li>StreamIdleTimeout 保护，前端显示“思考中”状态行就地更新为“重试中”。</li></ul></li><li>子任务并发与超时 <ul><li>dispatchSubtasksParallel 使用 Set 跟踪在途任务，size 恒等于真实并发数；computeSubtaskLoopTimeoutMs 限制子任务整体超时。</li></ul></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L824-L977" target="_blank" rel="noreferrer">src/background/react-loop.js#L824-L977</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L867-L886" target="_blank" rel="noreferrer">src/background/react-loop.js#L867-L886</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1410-L1451" target="_blank" rel="noreferrer">src/background/react-loop.js#L1410-L1451</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L2476-L2496" target="_blank" rel="noreferrer">src/background/react-loop.js#L2476-L2496</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L2424-L2427" target="_blank" rel="noreferrer">src/background/react-loop.js#L2424-L2427</a></li></ul><h2 id="调试与故障排查" tabindex="-1">调试与故障排查 <a class="header-anchor" href="#调试与故障排查" aria-label="Permalink to &quot;调试与故障排查&quot;">​</a></h2><ul><li>常见问题 <ul><li>工具确认弹窗不出现：检查 keepalive port 是否存在、INTERACTION_DISPLAYED 回执是否送达、会话归属匹配。</li><li>子任务卡住：检查子任务是否被 cancel、是否触发循环检测硬停、是否完成度校验 rerunEnabled 配置不当。</li><li>上下文超限 400：查看 contextHealAttempts 自愈次数与 trimMessagesByBudget 裁剪比例。</li><li>MCP 工具未生效：确认 loadMcpTools 是否成功、服务器是否禁用、mcpToolIds 去重。</li></ul></li><li>诊断要点 <ul><li>执行日志节点 status 是否为 processing/failed/cancelled，observation 是否被截断。</li><li>loop-detector 的 nudge/stop 原因与 params。</li><li>reflection 的 overallScore 与 decision（passed/revised/needs_improvement）。</li><li>checkpoint 是否落盘成功（read-back 验证）。</li></ul></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L285-L450" target="_blank" rel="noreferrer">src/background/react-loop.js#L285-L450</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1514-L1585" target="_blank" rel="noreferrer">src/background/react-loop.js#L1514-L1585</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/loop-detector.js#L304-L439" target="_blank" rel="noreferrer">src/background/loop-detector.js#L304-L439</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L259-L487" target="_blank" rel="noreferrer">src/background/react-reflection.js#L259-L487</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L551-L644" target="_blank" rel="noreferrer">src/background/tool-executor.js#L551-L644</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>ReAct 推理循环通过 reactLoopImpl 将“思考-行动-观察”主循环与工具执行、循环检测、子任务管理、反思机制与错误恢复有机整合。其设计强调：</p><ul><li>安全性：敏感操作确认、不可信内容包装、内网访问门控。</li><li>鲁棒性：检查点持久化与恢复、上下文超限自愈、流式空闲超时。</li><li>可扩展性：MCP/RAG 工具动态注册、完成度校验编排、反思策略解耦。</li><li>性能：Token 预算与批量压缩、工具结果卸载、并行子任务并发受限。</li></ul><h2 id="附录-扩展指南" tabindex="-1">附录：扩展指南 <a class="header-anchor" href="#附录-扩展指南" aria-label="Permalink to &quot;附录：扩展指南&quot;">​</a></h2><ul><li>扩展新工具类型 <ul><li>在 tool-executor.js 中新增工具定义（id/category/type/function），若需后台执行则在 TOOL_EXECUTION_MAP 映射，并在 BG_HANDLERS 中实现 handler；若为 MCP/RAG 工具，确保 loadMcpTools/loadRagTools 能动态注册。</li><li>参考路径：<a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L551-L644" target="_blank" rel="noreferrer">src/background/tool-executor.js#L551-L644</a>。</li></ul></li><li>自定义 ReAct 行为 <ul><li>修改 shouldReflect 判断逻辑（react-reflection.js）以适配特定任务复杂度；调整 reflectOnResult 的质量阈值与修订策略。</li><li>参考路径：<a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L57-L79" target="_blank" rel="noreferrer">src/background/react-reflection.js#L57-L79</a>、<a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L259-L487" target="_blank" rel="noreferrer">src/background/react-reflection.js#L259-L487</a>。</li></ul></li><li>优化推理性能 <ul><li>调整 reactTokenBudget 计算与 trimMessages 阈值；启用 offloadLargeToolResult 卸载大结果；合理设置 PARALLELIZABLE_TOOLS 以提升并行度。</li><li>参考路径：<a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L824-L977" target="_blank" rel="noreferrer">src/background/react-loop.js#L824-L977</a>、<a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L867-L886" target="_blank" rel="noreferrer">src/background/react-loop.js#L867-L886</a>。</li></ul></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L551-L644" target="_blank" rel="noreferrer">src/background/tool-executor.js#L551-L644</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L57-L79" target="_blank" rel="noreferrer">src/background/react-reflection.js#L57-L79</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-reflection.js#L259-L487" target="_blank" rel="noreferrer">src/background/react-reflection.js#L259-L487</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L824-L977" target="_blank" rel="noreferrer">src/background/react-loop.js#L824-L977</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L867-L886" target="_blank" rel="noreferrer">src/background/react-loop.js#L867-L886</a></li></ul>`,88)])])}const p=r(a,[["render",i]]);export{h as __pageData,p as default};
